THEME_IDS: dict[str, int] = {t.key: t.id for t in THEMES}
PRESETS: dict[str, Theme] = {t.key: t for t in THEMES}


def theme_by_id(theme_id: int) -> Theme | None:
    return next((t for t in THEMES if t.id == theme_id), None)


def swatch(theme_id: int, index: int) -> Swatch | None:
    """Palette entry for wire index 1..12 (0 or out of range: None = role default)."""
    t = theme_by_id(theme_id)
    if t is None or not 1 <= index <= len(t.palette):
        return None
    return t.palette[index - 1]
